import{_ as t,c as n,o as s,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易通論","description":"周易通論 - 周易通論","frontmatter":{"title":"周易通論","description":"周易通論 - 周易通論"},"headers":[],"relativePath":"classics/tonglun/001.md","filePath":"classics/tonglun/001.md"}'),r={name:"classics/tonglun/001.md"};function o(c,a,i,p,d,u){return s(),n("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易通論",tabindex:"-1"},[l("周易通論 "),e("a",{class:"header-anchor",href:"#周易通論","aria-label":"Permalink to “周易通論”"},"​")],-1),e("p",null,"欽定四庫全書經部一",-1),e("p",null,"易類提要",-1),e("p",null,"臣 等謹案：周易通論四卷，",-1),e("p",null,"國朝李光地撰。光地字厚庵，安溪人。康熙庚戌進士，官至大學士，諡文貞。是書綜論易理，各自為篇。一卷、二卷乃發明上下經大旨，三卷、四卷則發明繫辭、說卦、序卦、雜卦之義。冠以易本、易教二篇，次及卦、爻、象、彖、時位，反覆辨說，詳盡無遺。光地於易學最為深邃，得其傳者，如楊名時等諸人，各有著述，皆以光地為宗，而終不及其師之純粹。雖其言專主義理而略象數，未免沿襲宋儒流派，尚未能求之漢學，以參伍而折衷之。然平正通達，不為艱深奧渺之談，於四聖之精微，實能確有所見。其論復、無妄、離、中孚四卦，為聖賢之心學，尤發前人所未發。而「鬼神之情狀，繼善成性」之說，亦與中庸、論語相為表裡，正非村塾講章、剽竊庸腐之家所可得而擬議矣。乾隆四十六年十月恭校上，",-1),e("p",null,"總纂官 臣 紀昀、 臣 陸錫熊、 臣 孫士毅，總校官 臣 陸費墀。",-1)])])}const f=t(r,[["render",o]]);export{_ as __pageData,f as default};
